/**
 * Maps a city to its region via the fixed city-to-region table
 * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD). Returns {@code UNKNOWN}
 * when the city is absent or not in the table.
 */
default String cityRegion(String city) {
    if (city == null) {
        return "UNKNOWN";
    }
    switch (city) {
        case "Sydney":
            return "NSW";
        case "Melbourne":
            return "VIC";
        case "Brisbane":
            return "QLD";
        default:
            return "UNKNOWN";
    }
}

/**
 * Resolves the region from a 4-digit postcode range, or {@code null} when the
 * postcode is absent, malformed, or in no known range.
 */
default String regionFromPostcode(String postcode) {
    if (postcode == null) {
        return null;
    }
    int code;
    try {
        code = Integer.parseInt(postcode.trim());
    }
    catch (NumberFormatException ex) {
        return null;
    }
    if (code >= 2000 && code <= 2099) {
        return "NSW";
    }
    if (code >= 3000 && code <= 3099) {
        return "VIC";
    }
    if (code >= 4000 && code <= 4099) {
        return "QLD";
    }
    return null;
}

